package com.casecraft.threads;
import java.util.*;import java.util.concurrent.Callable;
public class StatementAnalysisThread implements Callable<List<Map<String,Object>>> { private final List<Map<String,Object>> statements; public StatementAnalysisThread(List<Map<String,Object>> statements){this.statements=statements;} public List<Map<String,Object>> call(){List<Map<String,Object>> out=new ArrayList<>();for(int i=0;i<statements.size();i++)for(int j=i+1;j<statements.size();j++){String a=String.valueOf(statements.get(i).get("content")),b=String.valueOf(statements.get(j).get("content"));Set<String> wa=words(a),wb=words(b);Set<String> overlap=new HashSet<>(wa);overlap.retainAll(wb);if(!a.isBlank()&&!b.isBlank()&&overlap.size()>=3&&!a.equalsIgnoreCase(b))out.add(Map.of("type","REVIEW_SIMILARITY","severity","REVIEW","message","Statements share key terms. Compare their details manually.","items",List.of(statements.get(i).get("speaker"),statements.get(j).get("speaker"))));}return out;}private Set<String> words(String s){Set<String> out=new HashSet<>();for(String w:s.toLowerCase().replaceAll("[^\\p{L}\\p{N} ]"," ").split("\\s+"))if(w.length()>3)out.add(w);return out;} }
